head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.gDepCd = js_dep_cd;

/**
팝업 닫을때 알림 스케쥴를 재 기동 해준다.
그리고 팝업창 온 오프 여부를 저장한다.
 **/
window.onunload = function() {
    // alert(opener.frame.Provider("/top" ));

    if ($c.frame.path("/top") !== null) {
        // 스케쥴러를 재 실행해도 index에서 alramList명이 조회 되기때문에 다시뜨지는 않음 정상적으로 30초 후에 뜸
        $c.frame.path("/top").fn_alram_schedule();
        if (chk_active.checked) {
            $c.frame.path("/top").alram_on_off_val = "Y";
        } else {
            $c.frame.path("/top").alram_on_off_val = "N";
        }
    }
};

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        // 패널라운드 처리
        $c.cm.PanelToGroupBox(panel_1);

        // top.jsp 의 alram_on_off_val 값 초기화
        $c.frame.path("/top").alram_on_off_val = "Y";

        // 알림소리
        scwin.setWave();

        // 조회 - 알림소리가 안나서 1초 지연
        setTimeout("fn_search()", 1000);

        // 스케쥴러 시작
        setInterval('fn_search()', 30000);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF90500.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_Close_onclick
 * @description img_Close 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF90500.img_Close_onclick" });
    }
};

/**
 * @method
 * @name grd_List_OnDblClick
 * @description grd_List 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_OnDblClick = async function(row, colid) {
    try {
        const noti_svc_seq = grd_ds.getCellData(row, "NOTI_SVC_SEQ");
        if (colid === "COL2") {
            const go_url = grd_ds.getCellData(row, "URL");
            if (go_url === "STF30001") {
                const STF30001_URL = "/dsclmgt/ULDSTF30001.gfm?src=JSP&cmd=C&isFnSrch=N";
                // frame.CreateFrame("child01", STF30001_URL, "일정조회", 20, 10, 10, 20,"");

                $c.frame.path("../").GWinOpen("child01", STF30001_URL, "일정조회", 20, 10, 10, 20, "");
            } else if (go_url === "STF08051A") {
                const STF08051A_URL = "/etn/ULDSTF08051.gfm?isEaryRedmpt=Y"; // 조기상환에 의한 상장폐지 ETN의 경우 '조기상환에 의한 상자폐지'탭의 신규 버튼이 눌려진 형태로 표시하기 위해... 20170302 KBoY
                $c.frame.path("../").GWinOpen("child01", STF08051A_URL, "조기상환 ETN", 20, 10, 1024, 600, "");
            } else {
                if (go_url.length > 0) {
                    $c.frame.path("/top").WinOpenP(go_url);
                }
            }
            // 확인 update 처리
            if (noti_svc_seq.length > 0) {
                await scwin.viewCheck(noti_svc_seq);
            }
        } else if (colid === "COL1") {
            // 회사명/종목명 더블 클릭시 확인 뷰 팝업 호출

            if (grd_ds.getCellData(row, "READ_YN") === "N") {
                $c.frame.path("../").fn_noti_open(noti_svc_seq);
                await scwin.viewCheck(noti_svc_seq);
            }
        } else if (colid === "CHECK_COL") {
            // 확인 여부 클릭시 확인 update 처리
            if (Number(grd_ds.getCellData(row, "TIME_SUM")) < 17) {
                if (noti_svc_seq.length > 0) {
                    await scwin.viewCheck(noti_svc_seq);
                }
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF90500.grd_List_OnDblClick" });
    }
};

/**
 * @method
 * @name dts_dscs_noti_alram_OnLoadError
 * @description dts_dscs_noti_alram 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.dts_dscs_noti_alram_OnLoadError = function() {
    // alert('');

    // frame.CloseFrame();

};

/**
 * @method
 * @name dts_dscs_noti_alram_OnLoadCompleted
 * @description dts_dscs_noti_alram 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_dscs_noti_alram_OnLoadCompleted = function(rowcount) {
    try {
        scwin.dsCopy();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF90500.dts_dscs_noti_alram_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name chk_read_hidden_onclick
 * @description chk_read_hidden 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.chk_read_hidden_onclick = function() {
    try {
        scwin.grdDsOrder();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF90500.chk_read_hidden_onclick" });
    }
};

/**
 * @method
 * @name grd_ds_OnFilter
 * @description grd ds On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.grd_ds_OnFilter = function(row) {
    try {
        if (!chk_read_hidden.checked) {
            // (확인 되었고 공시아닌것) || (처리완료고  타부서에서 처리된거, 확인완료 메세지) 는 숨김
            if ((grd_ds.getCellData(row, "READ_YN") === "Y" && grd_ds.getCellData(row, "STAT_CD_TYPE") === "C") ||
                (grd_ds.getCellData(row, "STAT_CD_TYPE") === "B" && grd_ds.getCellData(row, "DEP_CHECK") === "N" && grd_ds.getCellData(row, "READ_YN") === "Y")) {
                return false;

                // 처리완료.자기부서꺼
            } else if (grd_ds.getCellData(row, "STAT_CD_TYPE") === "B" && grd_ds.getCellData(row, "DEP_CHECK") === "Y") {
                // 처리 완료이나 서식대분류코드가 zz 인것중 미확인 이면서  공시승인 지연 메세지가 아닌것은 숨기지 않음
                if (grd_ds.getCellData(row, "FORM_UPCLSS_CD") === "zz" && grd_ds.getCellData(row, "READ_YN") === "N" && grd_ds.getCellData(row, "COL2").indexOf("공시승인 지연") === -1) {
                    return true;
                } else {
                    return false;
                }
            } else {
                return true;
            }
        } else {
            return true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF90500.grd_ds_OnFilter" });
    }
};

/**
 * @method
 * @name grd_ds_OnLoadCompleted
 * @description grd_ds 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.grd_ds_OnLoadCompleted = function(rowcount) {
    // alert('grd_ds.OnLoadCompleted('+rowcount+')');

};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description 알림 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    const sbmOptions = {
        id : "sbm_dts_dscs_noti_alram",
        action : "/notisvc.do",
        ref : "",
        target : "dts_dscs_noti_alram=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name viewCheck
 * @description 확인처리
 * @param {*} noti_seq noti_seq
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.viewCheck = async function(noti_seq) {
    const sbmOptions = {
        id : "sbm_dts_dscs_noti_alram",
        action : "/notisvc.do",
        ref : "",
        target : "dts_dscs_noti_alram=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name chkAlert
 * @description 파생상품운영팀 알림소리
 * @returns {void}
 * @hidden N
 */
scwin.chkAlert = function() {
    // alert(dts_dscs_noti_alram.NameString(dts_dscs_noti_alram.CountRow,  "TIME_SUM_PR") + "_" + dts_dscs_noti_alram.CountRow);

    // 주식파생운영팀에 비상음 표출_2018.12.07
    let read_yn = "";
    let dep_cd = "";
    let sound_yn = "";
    let isNotiYn = false; // 경고음 출력 여부

    for (let i = dts_dscs_noti_alram.getRowCount(); i > 0; i--) {
        read_yn = dts_dscs_noti_alram.getCellData(i, "READ_YN");
        dep_cd = dts_dscs_noti_alram.getCellData(i, "DEP_CD");
        sound_yn = dts_dscs_noti_alram.getCellData(i, "SOUND_YN");

        //        alert(read_yn + "_" + sound_yn + "_" + dep_cd + "_" + gDepCd +"_"+soundCnt);

        if (read_yn === "N" && sound_yn === "Y" &&
            dep_cd !== null && scwin.gDepCd === dep_cd) {
            // 부서확인

            if (scwin.gDepCd === "4210") {
                isNotiYn = true;
                break;

                /*
                //경고음 출력
                if(soundCnt == 0)	{
                	playNotice();

                	setTimeout("stopNotice()", 5600);	//3번 loop 후 꺼지도록

                    //alert("!");
                }

                i = 0;			//경고음 한번만

                soundCnt++;
                 */
            } else if (scwin.gDepCd === "2430") {
                scwin.playNotice();
            }
        }
    }
    if (scwin.gDepCd === "4210") {
        if (isNotiYn) {
            scwin.playNotice();
        } else {
            scwin.stopNotice(); // 담당자 확인 후 목록 재조회 시 알림 중지 처리

        }
    }
};

/**
 * @method
 * @name dsCopy
 * @description 데이터 셋을 카피하여 사용한다. 이유는 정렬및 조회시 깜박임 방지
 * @returns {void}
 * @hidden N
 */
scwin.dsCopy = function() {
    grd_ds.removeAll();
    // grd_ds.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
    grd_ds.setJSON(dts_dscs_noti_alram.getRangeJSON(1, dts_dscs_noti_alram.getRowCount(), true));
    grd_ds.filter();
    if (chk_active.checked) {
        // 알람소리
        scwin.chkAlert();

        /** 화면에 다른 팝업이 떠 있으면 조회시 비활성화 하나
        2018-06-15 팝업있어도 무조건 활성화 시키게 변경

        var virWinID_value = frame.Provider("/top" ).Provider("../").gVirWinNum;
        virWinID_value ="../virWinID"+virWinID_value;

        var alram_frame =  frame.Provider("/top" ).Provider(virWinID_value);

        alram_frame.ChildWndCollection();

        var childCnt = alram_frame.CollectionLength;
        var pop_check = true;

        for( var i =0; i < childCnt ; i++ ){
        	var pageid = alram_frame.item(i).FrameID;

        	 var pop_frame = alram_frame.item(i);
        	 pop_frame.ChildWndCollection();

        	 for(var y =0; y < pop_frame.CollectionLength ;y++ ){

        		 if( pop_frame.item(y).FrameID != "NoData"){
        				pop_check = false;
        			}
        	 }

        	 pop_frame.DeleteCollection();
        }

        alram_frame.DeleteCollection();

        if(pop_check){
        	frame.FrameShow("showna");
        }
         **/
        frame.FrameShow("showna");
    }
    if (dts_dscs_noti_alram.getRowCount() > 0) {
        const no_count = grd_ds.getCellData(0, "NO_COUNT");
        //        if( Number(no_count) > 0){
        if (no_count !== "0|0") {
            $c.frame.path("/top").fn_alram_msg(no_count);
            grd_ds.setRowPosition(0, 0);
        } else {
            // frame.CloseFrame();

        }
    } else {
        // 2018-05-18 0건이여도 표시해줌

        // frame.CloseFrame();

    }
};

/**
 * @method
 * @name grdDsOrder
 * @description 전체 보기시 Unfilter시 정렬 틀어짐을 해결하기 위해 dataSet를 copy 해서 씀
 * @returns {void}
 * @hidden N
 */
scwin.grdDsOrder = function() {
    if (!chk_read_hidden.checked) {
        grd_ds.filter();
    } else {
        scwin.dsCopy();
    }
};

/**
 * @method
 * @name setWave
 * @description 소리 출력을 위한 설정
 * @returns {void}
 * @hidden N
 */
scwin.setWave = function() {
    if (scwin.gDepCd === "4210") {
        // 주식파생운영팀
        panelWav.style.display = 'none';
        panelWav.innerHTML = "<embed src='/common/alert.wav' name='alertWave' autostart='false' loop='true'>";
    } else if (scwin.gDepCd === "2430") {
        panelWav.style.display = 'none';
        panelWav.innerHTML = "<embed src='/common/bonds_alert.wav' name='alertWave' autostart='false' loop='false'>";
    }
};

/**
 * @method
 * @name playNotice
 * @description play Notice 처리
 * @returns {void}
 * @hidden N
 */
scwin.playNotice = function() {
    alertWave.play();
};

/**
 * @method
 * @name stopNotice
 * @description stop Notice 처리
 * @returns {void}
 * @hidden N
 */
scwin.stopNotice = function() {
    alertWave.stop();
};
